-- Require a linked Cfx.re account (fivem: identifier)
local CHECK_CFX = true

-- Check for FiveM auto-generated names (e.g. SlowBat8645)
local CHECK_NAME = true

-- Only used when CHECK_NAME = true
-- true  = block auto-named players from joining
-- false = show a warning card, let them continue after confirming
local BLOCK = true

-- FiveM default names: <Adjective><Animal><4 digits>, e.g. SlowBat8645, BreezyDuck8244
local function isAutoName(name)
    return name and name:match('^%u%l+%u%l+%d%d%d%d$') ~= nil
end

local function buildCard(name)
    local actions = {
        { type = 'Action.Submit', title = 'I Understand, Continue', data = { action = 'continue' } },
    }
    if BLOCK then actions = {} end

    return json.encode({
        type = 'AdaptiveCard',
        version = '1.3',
        ['$schema'] = 'http://adaptivecards.io/schemas/adaptive-card.json',
        body = {
            { type = 'TextBlock', text = 'Please Change Your Name', size = 'ExtraLarge', weight = 'Bolder', color = 'Warning' },
            { type = 'TextBlock', wrap = true, text = ('Your name **%s** is auto-generated by FiveM.'):format(name) },
            { type = 'TextBlock', wrap = true, spacing = 'Medium', text = 'How to change it:' },
            { type = 'TextBlock', wrap = true, spacing = 'None', text = '1. Go back to the FiveM main menu' },
            { type = 'TextBlock', wrap = true, spacing = 'None', text = '2. Open Settings and change your Name' },
            { type = 'TextBlock', wrap = true, spacing = 'None', text = '3. Reconnect to the server' },
        },
        actions = actions,
    })
end

AddEventHandler('playerConnecting', function(name, _, deferrals)
    local src = source

    -- Cfx.re account required (gives a "fivem:" identifier)
    if CHECK_CFX and not GetPlayerIdentifierByType(src, 'fivem') then
        deferrals.defer()
        Wait(0)
        deferrals.done('You must link a Cfx.re account to join. In FiveM, open Settings > Account, sign in to Cfx.re, then reconnect.')
        return
    end

    if not CHECK_NAME or not isAutoName(name) then return end

    deferrals.defer()
    Wait(0)
    deferrals.update('Checking your name...')
    Wait(100)

    if BLOCK then
        deferrals.done(('Your name "%s" is auto-generated by FiveM. Change it in FiveM Settings and reconnect.'):format(name))
        return
    end

    local finished = false
    local ok, card = pcall(buildCard, name)
    if not ok then
        print('[filo_namecheck] card build failed: ' .. tostring(card))
        deferrals.done()
        return
    end

    deferrals.presentCard(card, function()
        if finished then return end
        finished = true
        deferrals.done()
    end)

    -- safety net: never leave a player hanging on the card
    SetTimeout(120000, function()
        if not finished then
            finished = true
            deferrals.done()
        end
    end)
end)
